export function localStorageGet(t,e=""){try{return null===localStorage.getItem(t)?e:JSON.parse(localStorage.getItem(t))}catch{return e}}export function localStorageSet(t,e){try{return localStorage.setItem(t,JSON.stringify(e))}catch{return!1}}export function localStorageDelete(t){try{return localStorage.removeItem(t)}catch{return!1}}